% !TEX program = xelatex
% ============================================================
%  Chinese Academic Beamer · CUFE School-of-Finance Style
%  Overleaf 编译说明：
%    1. 上传本 .tex + figures/ 整个文件夹
%    2. Settings → Compiler → XeLaTeX
%    3. Recompile 两次（让目录页对齐）
% ============================================================
\documentclass[10pt,aspectratio=169]{beamer}

% ---- 中文支持（fandol，免系统字体） --------------------------
\usepackage[UTF8,fontset=fandol]{ctex}

% ---- 主题：空主题 + 自建 CUFE 模板 ---------------------------
\usetheme{default}
\useinnertheme{circles}

% ---- 常用宏包 ------------------------------------------------
\usepackage{booktabs}
\usepackage{array}
\usepackage{graphicx}
\usepackage{amsmath}
\usepackage{amssymb}
\usepackage{makecell}
\usepackage{xcolor}
\usepackage{tikz}
\usetikzlibrary{arrows.meta,positioning,fit,calc}

% ---- 色板（锁定） --------------------------------------------
\definecolor{cufenavy}{HTML}{1F3A60}   % 深蓝（顶部色带、结构色）
\definecolor{cufetext}{HTML}{2A2A2A}   % 帧标题 / 正文深色（不用蓝）
\definecolor{cuferule}{HTML}{7F8FAA}   % 页脚细分隔线

\setbeamercolor{structure}{fg=cufenavy}
\setbeamercolor{normal text}{fg=cufetext}
\setbeamercolor{alerted text}{fg=cufenavy}
\setbeamercolor{title}{fg=cufenavy}
\setbeamercolor{subtitle}{fg=cufenavy}
\setbeamercolor{frametitle}{fg=cufetext,bg=}
\setbeamercolor{item}{fg=cufenavy}
\setbeamercolor{block title}{fg=white,bg=cufenavy}
\setbeamercolor{block body}{fg=cufetext,bg=cufenavy!8}

% ---- 背景：顶部深蓝细条 + 右上 Logo（y = -0.70cm 为中心线）------
\setbeamertemplate{background}{%
  \begin{tikzpicture}[overlay,remember picture]
    \fill[cufenavy]
      (current page.north west) rectangle
      ([yshift=-0.15cm]current page.north east);
    \node[anchor=east,inner sep=0pt]
      at ([xshift=-0.45cm,yshift=-0.70cm]current page.north east)
      {\includegraphics[height=0.70cm,keepaspectratio]{figures/logo_cufe_small.png}};
    \draw[cuferule,line width=0.3pt]
      ([yshift=0.70cm]current page.south west) --
      ([yshift=0.70cm]current page.south east);
  \end{tikzpicture}%
}

% ---- 帧标题：TikZ 绝对定位，中心 y=-0.70cm 与 Logo 对齐 ---------
\setbeamertemplate{frametitle}{%
  \begin{tikzpicture}[overlay,remember picture]
    \node[anchor=north west,inner sep=0pt,
          text width=\dimexpr\paperwidth-5.0cm\relax,
          align=left]
      at ([xshift=0.40cm,yshift=-0.50cm]current page.north west)
      {\color{cufetext}\bfseries\large\insertframetitle};
  \end{tikzpicture}%
  \vspace*{0.55cm}%
}
\setbeamerfont{frametitle}{size=\large,series=\bfseries}

% ---- 页脚：章节名（左）+ 页码（右） -----------------------------
\setbeamertemplate{footline}{%
  \leavevmode%
  \hbox to \paperwidth{%
    \hspace*{0.55cm}%
    \begin{minipage}[b]{\dimexpr\paperwidth-2.8cm\relax}\vspace{0pt}%
      {\color{cufenavy}\footnotesize\insertsectionhead}%
    \end{minipage}%
    \hfill
    \begin{minipage}[b]{1.8cm}\vspace{0pt}%
      \raggedleft{\color{cufenavy}\footnotesize%
        % 只显示当前帧号：\inserttotalframenumber 在 ctex + beamer 下
        % 偶发返回诡异值（"80" 等），直接放弃 "X / N" 格式更稳
        \insertframenumber}%
    \end{minipage}%
    \hspace*{0.55cm}%
  }%
  \vspace{0.20cm}%
}
\setbeamertemplate{navigation symbols}{}
\AtBeginSection[]{}

% ---- 字号与 itemize 样式 ------------------------------------
\setbeamerfont{title}{size=\LARGE,series=\bfseries}
\setbeamerfont{subtitle}{size=\large}
\setbeamerfont{author}{size=\Large}
\setbeamerfont{institute}{size=\large}
\setbeamerfont{date}{size=\normalsize}
\setlength{\leftmargini}{1.4em}
\setbeamertemplate{itemize item}{\scriptsize\raise1.2pt\hbox{\color{cufenavy}\textbullet}}
\setbeamertemplate{itemize subitem}{\scriptsize\raise1.2pt\hbox{\color{cufenavy}$\circ$}}
\setbeamertemplate{itemize subsubitem}{\scriptsize\raise1.2pt\hbox{\color{cufenavy}$-$}}

% ---- 元数据（替换为论文实际信息） ------------------------------
\title[%
  [短标题·页脚用]%
]{%
  [论文全名 · 可长]%
}
\subtitle{}
\author[%
  [答辩人]%
]{%
  [答辩人]%
}
\institute[%
  [机构短名]%
]{%
  [机构全名]~~[年级 / 专业]\\[0.6em]
  指导教师：[教师 1] 教授~~\textbullet~~[教师 2] 教授%
}
\date[%
  [年份]%
]{%
  博士学位论文答辩~~[年份]%
}

% ============================================================
\begin{document}

% ============================================================
% 封面：大 logo + 居中标题（独立背景）
% ============================================================
{%
  \setbeamertemplate{background}{%
    \begin{tikzpicture}[overlay,remember picture]
      \fill[cufenavy]
        (current page.north west) rectangle
        ([yshift=-0.35cm]current page.north east);
      \node[anchor=north west,inner sep=0pt]
        at ([xshift=0.7cm,yshift=-0.85cm]current page.north west)
        {\includegraphics[width=6.4cm,keepaspectratio]{figures/logo_cufe_full.png}};
      \draw[cuferule,line width=0.4pt]
        ([yshift=0.85cm]current page.south west) --
        ([yshift=0.85cm]current page.south east);
    \end{tikzpicture}%
  }
  \begin{frame}[plain,noframenumbering]
    \vspace*{3.2cm}
    \begin{center}
      {\color{cufenavy}\bfseries\fontsize{24pt}{30pt}\selectfont
       [主标题第一行]\\[0.3em]
       [主标题第二行]}\\[0.6em]

      {\color{cufenavy}\itshape\large
       ——[副标题]}

      \vspace{1.2cm}
      {\color{cufetext}\Large\bfseries 答辩人：\,[答辩人姓名]}\\[0.5em]
      {\color{cufetext}\large 指导教师：[教师 1] 教授~~\textbullet~~[教师 2] 教授}\\[0.4em]
      {\color{cufetext}\normalsize [机构名]~~\textbullet~~[年级 / 专业]}
    \end{center}
    \vfill
    \begin{center}
      {\color{cufenavy}\normalsize\bfseries 博士学位论文答辩~~\textbullet~~[年份]}
    \end{center}
  \end{frame}
}

% ============================================================
% 目录：页脚留空
% ============================================================
{%
  \setbeamertemplate{footline}{\vbox to 0.9cm{\vfill}}
  \begin{frame}[noframenumbering]{目录}
    \vspace{0.4em}
    \tableofcontents[hideallsubsections]
  \end{frame}
}

% ============================================================
\section{研究背景与问题}
% ============================================================

% ---- §1 背景段落帧（按时长扩充 2-8 帧） ------------------------

\begin{frame}{研究背景（一）：[背景主题 1]}
  [首段：2--3 句话描述研究背景的第一个要点，关键词 \textbf{粗体} 突出。]

  \vspace{0.4em}
  [次段：2--3 句话描述第二个要点。\textbf{粗体} 突出。]

  \vspace{0.4em}
  [末段：收束句，\textbf{突出研究锚点}。]
\end{frame}

\begin{frame}{研究背景（二）：[背景主题 2]}
  [此处继续用段落文字描述背景。]
\end{frame}

% ---- 研究问题 -----------------------------------------------

\begin{frame}{研究问题：一个核心问题 + N 条实证线索}
  \begin{block}{核心问题}
    [一句话核心研究问题]
  \end{block}

  \vspace{0.4em}
  \begin{itemize}
    \item \textbf{Q1（[属性 1]，第四章）} [问题描述]
    \item \textbf{Q2（[属性 2]，第五章）} [问题描述]
    \item \textbf{Q3（[属性 3]，第六章）} [问题描述]
  \end{itemize}
\end{frame}

% ---- X → M → Y 框架帧（必填） ---------------------------------

\begin{frame}{研究框架：X → M → Y 的整体识别逻辑}
\vspace{-0.4em}
\begin{center}
\begin{tikzpicture}[
    xbox/.style={draw, rounded corners, fill=blue!15, draw=blue!60!black,
                 minimum width=2.8cm, minimum height=1.10cm,
                 font=\small\bfseries, align=center},
    mbox/.style={draw, rounded corners, fill=orange!12, draw=orange!70!black,
                 minimum width=4.4cm, minimum height=0.70cm,
                 font=\scriptsize, align=center},
    ybox/.style={draw, rounded corners, fill=green!15, draw=green!55!black,
                 minimum width=2.6cm, minimum height=5.8cm,
                 font=\small\bfseries, align=center},
    arr/.style={-Latex, semithick, gray!70!black}]

  \node[xbox] (X1) at (0, 2.6)  {[X1]\\\scriptsize 第四章 · [变量]};
  \node[xbox] (X2) at (0, 0)    {[X2]\\\scriptsize 第五章 · [变量]};
  \node[xbox] (X3) at (0,-2.6)  {[X3]\\\scriptsize 第六章 · [变量]};

  \node[mbox] (M1a) at (5.0, 3.0) {[通道 1a]};
  \node[mbox] (M1b) at (5.0, 2.2) {[通道 1b]};
  \node[mbox] (M2a) at (5.0, 0.4) {[通道 2a]};
  \node[mbox] (M2b) at (5.0,-0.4) {[通道 2b]};
  \node[mbox] (M3a) at (5.0,-2.2) {[通道 3a]};
  \node[mbox] (M3b) at (5.0,-3.0) {[通道 3b]};

  \node[ybox] (Y) at (10.2, 0) {[Y 标题]\\[0.5em]
      \scriptsize [Y 子变量]};

  \foreach \x/\m in {X1/M1a, X1/M1b, X2/M2a, X2/M2b, X3/M3a, X3/M3b}
    \draw[arr] (\x.east) -- (\m.west);
  \foreach \m in {M1a, M1b, M2a, M2b, M3a, M3b}
    \draw[arr] (\m.east) -- (Y.west);
\end{tikzpicture}
\end{center}
\vspace{-0.4em}
{\footnotesize 样本：[区间] [样本对象]，N = [观测数]。方法：[识别策略]。}
\end{frame}

% ============================================================
\section{文献综述与理论基础}
% ============================================================

\begin{frame}{文献脉络：两条主线 + 一处交叉空白}
  \textbf{主线 A：[主线 A 主题]}
  \begin{itemize}
    \item [派别 1] ([代表文献])：[论点]；
    \item [派别 2] ([代表文献])：[论点]。
