  \vspace{0.3em}
  \textbf{主线 B：[主线 B 主题]}
  \begin{itemize}
    \item [路径 1] ([代表文献])；
    \item [路径 2] ([代表文献])。
  \end{itemize}

  \vspace{0.3em}
  \textbf{交叉空白：} A $\cap$ B —— "[尚未被系统回答的问题]" —— \textbf{至今无系统回答}。
\end{frame}

\begin{frame}{理论基础：三视角一页对照}
