\section{三章综合对比与研究结论}
% ============================================================

\begin{frame}{三章综合对比：机制互补、情境依赖递减}
\centering\scriptsize
\setlength{\tabcolsep}{4pt}
\renewcommand{\arraystretch}{1.12}
\begin{tabular}{p{1.9cm} p{3.0cm} p{3.3cm} p{3.3cm}}
  \toprule
  对比维度 & 第四章 · [X1] & 第五章 · [X2] & 第六章 · [X3] \\
